const pages=$input.all().map(i=>i.json);
if(!pages.length)throw new Error('No lead pages returned.');
if(pages.at(-1).body?.next_starting_after)throw new Error('Lead pagination limit reached. No writes allowed.');
const emails=new Set(),cursors=new Set();let rows=0;
for(const [pageIndex,p] of pages.entries()){const cursor=p.body?.next_starting_after;if(cursor!==undefined&&cursor!==null&&cursor!==''&&(typeof cursor!=='string'||!cursor.trim()))throw new Error('Malformed pagination cursor.');if(pageIndex<pages.length-1&&(cursor===undefined||cursor===null||cursor===''))throw new Error('A nonfinal page has no continuation cursor.');
 if(p.statusCode!==200||!Array.isArray(p.body?.items))throw new Error('Invalid lead response.');
 if(p.body.next_starting_after){if(cursors.has(p.body.next_starting_after))throw new Error('Repeated lead cursor.');cursors.add(p.body.next_starting_after);}
 for(const r of p.body.items){rows++;if(r.status!==-2)throw new Error('Lead filter returned a non-unsubscribed record.');const e=typeof r.email==='string'?r.email.trim().toLowerCase():'';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e))throw new Error('Unsubscribed record has invalid email. Review source before syncing.');emails.add(e);}
}
return [{json:{emails:[...emails],sourceRows:rows,sourcePages:pages.length}}];

const pages=$input.all().map(i=>i.json),source=$('Collect unsubscribed emails').first().json,cfg=$('Sync settings').first().json;
if(typeof cfg.applyChanges!=='boolean'||!Number.isSafeInteger(cfg.maxNewBlocks)||cfg.maxNewBlocks<1||cfg.maxNewBlocks>1000)throw new Error('Invalid sync settings.');
if(!pages.length||pages.at(-1).body?.next_starting_after)throw new Error('Block-list pagination incomplete.');
const blocked=new Set(),domains=new Set(),cursors=new Set();
for(const [pageIndex,p] of pages.entries()){const cursor=p.body?.next_starting_after;if(cursor!==undefined&&cursor!==null&&cursor!==''&&(typeof cursor!=='string'||!cursor.trim()))throw new Error('Malformed pagination cursor.');if(pageIndex<pages.length-1&&(cursor===undefined||cursor===null||cursor===''))throw new Error('A nonfinal page has no continuation cursor.');if(p.statusCode!==200||!Array.isArray(p.body?.items))throw new Error('Invalid block-list response.');if(p.body.next_starting_after){if(cursors.has(p.body.next_starting_after))throw new Error('Repeated block-list cursor.');cursors.add(p.body.next_starting_after);}for(const r of p.body.items){if(typeof r.bl_value!=='string'||!r.bl_value.trim()||typeof r.is_domain!=='boolean')throw new Error('Block entry missing value.');const v=r.bl_value.trim().toLowerCase();if(r.is_domain===true)domains.add(v);else blocked.add(v);}}
const missing=source.emails.filter(e=>!blocked.has(e)&&!domains.has(e.split('@')[1]));
if(missing.length>cfg.maxNewBlocks)throw new Error('New-block limit exceeded. Review source and raise maxNewBlocks deliberately.');
return [{json:{applyChanges:cfg.applyChanges,missing,sourceEmails:source.emails.length,alreadyBlocked:source.emails.length-missing.length,sourcePages:source.sourcePages,blockPages:pages.length,writeCount:0}}];

const wanted=new Set($('Plan missing blocks').first().json.missing),seen=new Set(),ids=new Set();
const out=$input.all().map(i=>{const r=i.json,email=typeof r.bl_value==='string'?r.bl_value.trim().toLowerCase():'';if(typeof r.id!=='string'||!/^[A-Za-z0-9-]+$/.test(r.id)||!wanted.has(email)||r.is_domain!==false||seen.has(email)||ids.has(r.id))throw new Error('Create response did not match the planned email. Read the block list before retrying.');seen.add(email);ids.add(r.id);return {json:{id:r.id,email}};});
if(seen.size!==wanted.size)throw new Error('Create responses are incomplete. Check provider before retrying.');return out;

const plan=$('Plan missing blocks').first().json,created=$('Validate created blocks').all().map(i=>i.json);
if(created.length!==plan.missing.length)throw new Error('Created block count does not match the plan.');
const expected=new Map(created.map(r=>[r.id,r.email])),wanted=new Set(plan.missing),seen=new Set();
if(expected.size!==created.length||new Set(created.map(r=>r.email)).size!==wanted.size||created.some(r=>!wanted.has(r.email)))throw new Error('Created block identities are not one-to-one with the plan.');
for(const i of $input.all()){const r=i.json,e=typeof r.bl_value==='string'?r.bl_value.trim().toLowerCase():'';if(!expected.has(r.id)||expected.get(r.id)!==e||r.is_domain!==false||seen.has(r.id))throw new Error('Block-list readback mismatch.');seen.add(r.id);}
if(seen.size!==wanted.size)throw new Error('Block-list readback incomplete.');
return [{json:{sourceEmails:plan.sourceEmails,alreadyBlocked:plan.alreadyBlocked,writeCount:seen.size,verified:true,mode:'applied'}}];
